+	struct drm_fabric_desc zero = {
+		.type = (enum drm_fabric_type)0,
+		.instance_id = 0x5a5a,
+		.name = "test-type-zero",
+	};
+	struct drm_fabric_desc good = {
+		.type = DRM_FABRIC_TYPE_SYNTHETIC,
+		.instance_id = 0x5a5a,
+		.name = "test-type-good",
