+	enum qxm_sel qxm_type;
+	/* All *_len values below are SHRAM sizes in 64-bit words */
+	u32 rd_len;
+	u32 rddma_shram_len;
+	/* SHRAM start offsets (in 64-bit words), indexed by enum qaif_dma_type */
+	u32 rddma_shram_start_addr[2];
+	u32 wr_len;
+	u32 wrdma_shram_len;
+	u32 wrdma_shram_start_addr[2];
