+	/* configure normal test mode */
+	r = yt8824_utp_normal_test_mode_paged(phydev);
+	if (ret >= 0 && r < 0)
+		ret = r;
+	/* sds soft reset and disable isolation */
+	r = yt8824_sds_isolate_and_softreset_paged(phydev);
+	if (ret >= 0 && r < 0)
+		ret = r;
+	return ret;
